-- Additive Preview social storage. Archive the two unregistered/unused legacy definitions.
CREATE TABLE IF NOT EXISTS connect_retired_definitions(starter_key TEXT PRIMARY KEY,data TEXT NOT NULL,retired_at TEXT NOT NULL);
INSERT INTO cf_commit_guards(id,ok) VALUES('connect-six-migration',CASE WHEN NOT EXISTS(SELECT 1 FROM create_starter_selections WHERE starter_key IN('enchanted-forest','outer-space')) AND NOT EXISTS(SELECT 1 FROM connect_memberships WHERE group_id IN('global:enchanted-forest','global:outer-space')) THEN 1 ELSE 0 END);
INSERT OR IGNORE INTO connect_retired_definitions SELECT starter_key,json_object('group_id',group_id,'display_name',display_name,'starter_image_id',starter_image_id),strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM connect_groups WHERE starter_key IN('enchanted-forest','outer-space');
DELETE FROM connect_groups WHERE starter_key IN('enchanted-forest','outer-space');
DELETE FROM cf_commit_guards WHERE id='connect-six-migration';
CREATE TABLE IF NOT EXISTS connect_messages(server_seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,group_id TEXT NOT NULL REFERENCES connect_groups(group_id),user_id TEXT REFERENCES create_starter_profiles(owner_id) ON DELETE SET NULL,display_name TEXT NOT NULL,body TEXT NOT NULL,client_message_id TEXT NOT NULL,send_hash TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,edited_at TEXT,deleted_at TEXT,revision INTEGER NOT NULL DEFAULT 1 CHECK(revision BETWEEN 1 AND 9007199254740991),UNIQUE(group_id,user_id,client_message_id));
CREATE INDEX IF NOT EXISTS connect_messages_group_seq ON connect_messages(group_id,server_seq);
CREATE TABLE IF NOT EXISTS connect_message_events(cursor INTEGER PRIMARY KEY AUTOINCREMENT,group_id TEXT NOT NULL REFERENCES connect_groups(group_id),message_id TEXT NOT NULL REFERENCES connect_messages(id),kind TEXT NOT NULL CHECK(kind IN('created','updated','deleted')),created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS connect_events_group_cursor ON connect_message_events(group_id,cursor);
CREATE TRIGGER IF NOT EXISTS connect_message_created AFTER INSERT ON connect_messages BEGIN INSERT INTO connect_message_events(group_id,message_id,kind,created_at) VALUES(NEW.group_id,NEW.id,'created',NEW.updated_at); END;
CREATE TRIGGER IF NOT EXISTS connect_message_changed AFTER UPDATE ON connect_messages WHEN NEW.revision<>OLD.revision BEGIN INSERT INTO connect_message_events(group_id,message_id,kind,created_at) VALUES(NEW.group_id,NEW.id,CASE WHEN NEW.deleted_at IS NOT NULL THEN 'deleted' ELSE 'updated' END,NEW.updated_at); END;
CREATE TRIGGER IF NOT EXISTS connect_message_account_removed AFTER UPDATE OF user_id ON connect_messages WHEN NEW.user_id IS NULL AND OLD.user_id IS NOT NULL BEGIN UPDATE connect_messages SET display_name='Deleted account',body='',deleted_at=COALESCE(deleted_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now'),revision=revision+1 WHERE id=NEW.id; END;
CREATE TABLE IF NOT EXISTS connect_message_operations(owner_id TEXT NOT NULL REFERENCES create_starter_profiles(owner_id) ON DELETE CASCADE,group_id TEXT NOT NULL,operation_id TEXT NOT NULL,request_hash TEXT NOT NULL,message_id TEXT NOT NULL REFERENCES connect_messages(id),created_at TEXT NOT NULL,PRIMARY KEY(owner_id,group_id,operation_id));
CREATE TABLE IF NOT EXISTS connect_rate_windows(owner_id TEXT NOT NULL REFERENCES create_starter_profiles(owner_id) ON DELETE CASCADE,minute INTEGER NOT NULL,mutations INTEGER NOT NULL CHECK(mutations BETWEEN 0 AND 60),PRIMARY KEY(owner_id,minute));
CREATE INDEX IF NOT EXISTS connect_rate_expiry ON connect_rate_windows(minute);
